// venue_master.js — generated by Generate Module

const { createApp } = Vue;

createApp({
  data() {
    return {
      systemName: SYSTEM_NAME,
      title:      '',
      loading: false,
      saving:  false,
      saved:   false,
      error:   '',
      isExisting: false,
      form: {
        ref: '',
      venue_name: '',
      address: '',
      venue_category_ref: '',
      venue_category_name: '',
      capacity: 0,
      layout: '',
      contact_name: '',
      contact_phone: '',
      contact_email: '',
      },
    };
  },

  computed: {
    isDirty() {
      return (
        this.form.venue_name !== '' ||
        this.form.address !== '' ||
        this.form.venue_category_ref !== '' ||
        this.form.capacity !== 0 ||
        this.form.layout !== '' ||
        this.form.contact_name !== '' ||
        this.form.contact_phone !== '' ||
        this.form.contact_email !== ''
      );
    },
  },

  mounted() {
    this.fetchRefNumber();
    document.addEventListener('venue_master-selected', (e) => this.loadRecord(e.detail));
    document.addEventListener('vn-venue-category-selected', (e) => {
      this.form.venue_category_ref  = e.detail.ref;
      this.form.venue_category_name = e.detail.venue_category_name;
    });
  },

  methods: {
    fetchRefNumber() {
      this.loading = true;
      axios.get('/server/general/module_data.php?system_name=' + this.systemName)
        .then(res => { this.form.ref = res.data.ref; this.title = res.data.module; })
        .catch(err => { this.error = 'Failed to load reference number.'; console.error(err); })
        .finally(() => { this.loading = false; });
    },

    clearVenueCategory() { this.form.venue_category_ref = ''; this.form.venue_category_name = ''; },

    onAdd()    { this.onReset(); this.fetchRefNumber(); },
    onPrint() {
      if (!this.form.ref) { this.error = 'No record to print. Search and select a saved record first.'; return; }
      axios.get('/modules/master_files/references/venue_master/venue_master_data.php?action=exists&ref=' + encodeURIComponent(this.form.ref))
        .then(res => {
          if (!res.data.exists) {
            this.error = 'No saved record found for this reference. Please search and select a record to print.';
            return;
          }
          const params = new URLSearchParams({
            ref: this.form.ref,
        venue_name: String(this.form.venue_name ?? ''),
        address: String(this.form.address ?? ''),
        venue_category_name: String(this.form.venue_category_name ?? ''),
        capacity: String(this.form.capacity ?? ''),
        layout: String(this.form.layout ?? ''),
        contact_name: String(this.form.contact_name ?? ''),
        contact_phone: String(this.form.contact_phone ?? ''),
        contact_email: String(this.form.contact_email ?? ''),
          });
          window.open('/modules/master_files/references/venue_master/venue_master_print.php?' + params.toString(), '_blank');
        })
        .catch(err => { this.error = 'Failed to verify record.'; console.error(err); });
    },
    onCancel() { this.onReset(); },
    onClose()  { this.onReset(); },

    onReset() {
      this.saved = false;
      this.error = '';
      this.isExisting = false;
      this.form.venue_name = '';
      this.form.address = '';
      this.form.venue_category_ref = '';
      this.form.venue_category_name = '';
      this.form.capacity = 0;
      this.form.layout = '';
      this.form.contact_name = '';
      this.form.contact_phone = '';
      this.form.contact_email = '';
    },

    onSave() {
      if (!this.isDirty) return;
      if (this.$refs.form && !this.$refs.form.reportValidity()) return;
      this.saving = true;
      this.saved  = false;
      this.error  = '';

      const proceed = (action) => {
        axios.post('/modules/master_files/references/venue_master/venue_master_data.php?action=' + action, this.form)
          .then(() => {
            this.saved = true;
            this.onReset();
            this.fetchRefNumber();
          })
          .catch(err => { this.error = err.response?.data?.error || 'Failed to save.'; console.error(err); })
          .finally(() => { this.saving = false; });
      };

      if (this.isExisting) {
        axios.get('/modules/master_files/references/venue_master/venue_master_data.php?action=exists&ref=' + encodeURIComponent(this.form.ref))
          .then(res => {
            if (!res.data.exists) { this.error = 'Record not found. Please search again.'; this.saving = false; return; }
            proceed('update');
          })
          .catch(err => { this.error = 'Failed to verify record.'; console.error(err); this.saving = false; });
      } else {
        proceed('save');
      }
    },

    loadRecord(data) {
      this.form.ref = data.ref;
      this.form.venue_name = data.venue_name;
      this.form.address = data.address;
      this.form.venue_category_ref = data.venue_category_ref ?? '';
      this.form.venue_category_name = data.m_venue_categories?.venue_category_name ?? '';
      this.form.capacity = data.capacity;
      this.form.layout = data.layout;
      this.form.contact_name = data.contact_name;
      this.form.contact_phone = data.contact_phone;
      this.form.contact_email = data.contact_email;
      this.isExisting = true;
      this.saved = false;
      this.error = '';
    },
  },
}).mount('#venue-master-app');